def count_digit_one(n):
    total = 0
    m = 1
    while m <= n:
        high, cur, low = n // (m * 10), n // m % 10, n % m
        if cur == 0:
            total += high * m
        elif cur == 1:
            total += high * m + low + 1
        else:
            total += (high + 1) * m
        m *= 10
    return total
